"""Semantic version parsing, comparison, and range matching.

Versions follow Semantic Versioning 2.0.0: ``MAJOR.MINOR.PATCH``, then an
optional pre-release (``-`` followed by dot-separated identifiers) and an
optional build (``+`` followed by dot-separated identifiers). Identifiers
are non-empty and made of ASCII letters, digits, and hyphens. Numeric parts
(MAJOR, MINOR, PATCH, and all-digit pre-release identifiers) must not have
leading zeros. Anything else is invalid and raises ``ValueError``.

Precedence (``compare``) follows the SemVer 2.0.0 rules: compare MAJOR,
MINOR, and PATCH numerically; a version with a pre-release is lower than
the same version without one; pre-release identifiers are compared left to
right, all-digit ones numerically and the rest in ASCII order, with
all-digit identifiers lower than the rest, and a shorter list lower when
all its identifiers equal the start of a longer one. Build metadata is
ignored.

Ranges (``satisfies``) are one or more comparator sets joined by ``||``; a
version satisfies the range if it satisfies any set. A set is one or more
comparators separated by whitespace, all of which must hold. A comparator
is a full version optionally prefixed by an operator:

- ``=`` (or no operator), ``>``, ``>=``, ``<``, ``<=``: by precedence.
- ``^X.Y.Z``: at least ``X.Y.Z`` and below the next version that changes
  the leftmost non-zero part, i.e. ``^1.2.3`` is ``>=1.2.3 <2.0.0``,
  ``^0.2.3`` is ``>=0.2.3 <0.3.0``, and ``^0.0.3`` is ``>=0.0.3 <0.0.4``.
- ``~X.Y.Z``: at least ``X.Y.Z`` and below ``X.(Y+1).0``.

A version with a pre-release satisfies a set only if some comparator in
that set has a pre-release on the same MAJOR.MINOR.PATCH (so
``1.2.3-beta.2`` satisfies ``>=1.2.3-beta.1`` but not ``>=1.0.0``).
Invalid ranges raise ``ValueError``.
"""

from __future__ import annotations

import re
from dataclasses import dataclass

_VERSION_RE = re.compile(
    r"(?P<major>0|[1-9][0-9]*)\."
    r"(?P<minor>0|[1-9][0-9]*)\."
    r"(?P<patch>0|[1-9][0-9]*)"
    r"(?:-(?P<pre>[0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?"
    r"(?:\+(?P<build>[0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?"
)


@dataclass(frozen=True)
class Version:
    major: int
    minor: int
    patch: int
    prerelease: tuple[str, ...] = ()
    build: tuple[str, ...] = ()

    def __str__(self) -> str:
        """The version in canonical form, e.g. ``1.2.3-rc.1+build.5``."""
        text = f"{self.major}.{self.minor}.{self.patch}"
        if self.prerelease:
            text += "-" + ".".join(self.prerelease)
        if self.build:
            text += "+" + ".".join(self.build)
        return text


def parse(text: str) -> Version:
    """Parse a version string."""
    match = _VERSION_RE.fullmatch(text)
    if match is None:
        raise ValueError(f"invalid version: {text!r}")

    prerelease = match.group("pre")
    build = match.group("build")
    prerelease_ids = tuple(prerelease.split(".")) if prerelease else ()
    build_ids = tuple(build.split(".")) if build else ()

    for identifier in prerelease_ids:
        if (
            identifier.isascii()
            and identifier.isdigit()
            and len(identifier) > 1
            and identifier[0] == "0"
        ):
            raise ValueError(f"invalid version: {text!r}")

    return Version(
        major=int(match.group("major")),
        minor=int(match.group("minor")),
        patch=int(match.group("patch")),
        prerelease=prerelease_ids,
        build=build_ids,
    )


def _coerce(version: str | Version) -> Version:
    return version if isinstance(version, Version) else parse(version)


def _compare_prerelease(a: tuple[str, ...], b: tuple[str, ...]) -> int:
    if not a and not b:
        return 0
    if not a:
        return 1
    if not b:
        return -1

    for left, right in zip(a, b):
        left_numeric = left.isascii() and left.isdigit()
        right_numeric = right.isascii() and right.isdigit()
        if left_numeric and right_numeric:
            left_value, right_value = int(left), int(right)
            if left_value != right_value:
                return -1 if left_value < right_value else 1
        elif left_numeric:
            return -1
        elif right_numeric:
            return 1
        elif left != right:
            return -1 if left < right else 1

    if len(a) != len(b):
        return -1 if len(a) < len(b) else 1
    return 0


def _compare_versions(a: Version, b: Version) -> int:
    for left, right in (
        (a.major, b.major),
        (a.minor, b.minor),
        (a.patch, b.patch),
    ):
        if left != right:
            return -1 if left < right else 1
    return _compare_prerelease(a.prerelease, b.prerelease)


def compare(a: str | Version, b: str | Version) -> int:
    """Return -1, 0, or 1 as ``a`` has lower, equal, or higher precedence."""
    return _compare_versions(_coerce(a), _coerce(b))


def _caret_upper(version: Version) -> Version:
    if version.major != 0:
        return Version(version.major + 1, 0, 0)
    if version.minor != 0:
        return Version(0, version.minor + 1, 0)
    return Version(0, 0, version.patch + 1)


def _tilde_upper(version: Version) -> Version:
    return Version(version.major, version.minor + 1, 0)


_OPERATORS = (">=", "<=", ">", "<", "=", "^", "~")


def _parse_comparator(text: str) -> tuple[str, Version]:
    operator = "="
    rest = text
    for candidate in _OPERATORS:
        if text.startswith(candidate):
            operator = candidate
            rest = text[len(candidate) :]
            break
    if not rest:
        raise ValueError(f"invalid comparator: {text!r}")
    return operator, parse(rest)


def _parse_range(range_: str) -> list[list[tuple[str, Version]]]:
    sets: list[list[tuple[str, Version]]] = []
    for set_text in range_.split("||"):
        comparators = set_text.split()
        if not comparators:
            raise ValueError(f"invalid range: {range_!r}")
        sets.append([_parse_comparator(item) for item in comparators])
    return sets


def _satisfies_set(version: Version, comparators: list[tuple[str, Version]]) -> bool:
    if version.prerelease:
        allowed = any(
            comparator.prerelease
            and (
                comparator.major,
                comparator.minor,
                comparator.patch,
            )
            == (version.major, version.minor, version.patch)
            for _, comparator in comparators
        )
        if not allowed:
            return False

    for operator, comparator in comparators:
        if operator == "=":
            if _compare_versions(version, comparator) != 0:
                return False
        elif operator == ">":
            if _compare_versions(version, comparator) <= 0:
                return False
        elif operator == ">=":
            if _compare_versions(version, comparator) < 0:
                return False
        elif operator == "<":
            if _compare_versions(version, comparator) >= 0:
                return False
        elif operator == "<=":
            if _compare_versions(version, comparator) > 0:
                return False
        elif operator == "^":
            if _compare_versions(version, comparator) < 0:
                return False
            if _compare_versions(version, _caret_upper(comparator)) >= 0:
                return False
        elif operator == "~":
            if _compare_versions(version, comparator) < 0:
                return False
            if _compare_versions(version, _tilde_upper(comparator)) >= 0:
                return False
        else:  # pragma: no cover - operators are exhaustively handled above
            raise ValueError(f"invalid operator: {operator!r}")
    return True


def satisfies(version: str | Version, range_: str) -> bool:
    """Whether ``version`` is in ``range_``."""
    parsed_version = _coerce(version)
    return any(
        _satisfies_set(parsed_version, comparators)
        for comparators in _parse_range(range_)
    )

