"""Write and read Markdown (GitHub-flavored) pipe tables.

``format_table`` writes a header line, a delimiter line, and one line per
row, separated by ``\\n`` with no trailing newline. Every line is ``| ``,
then the column cells joined by `` | ``, then `` |``.

Cell text is ``str(value)``, or empty for ``None``, with each ``|``
escaped as ``\\|``. A row shorter than the header is padded with empty
cells; a longer one raises ``ValueError``. Each column is as wide as its
longest cell text (after escaping, and including the header), and at
least 3.

Cells are padded with spaces to the column width according to the
column's alignment: ``"left"`` or ``None`` pads on the right, ``"right"``
pads on the left, and ``"center"`` pads both sides equally, with any odd
space on the right. ``align`` gives one alignment per column (default all
``None``); any other value, or a list of the wrong length, raises
``ValueError``.

Delimiter cells are dashes filling the column width, with a colon replacing
the first dash for ``"left"``, the last for ``"right"``, and both for
``"center"`` (``:--``, ``--:``, ``:-:`` at width 3).

``parse_table`` reads such a table back, tolerating any padding and missing
leading or trailing pipes: it returns the header and the rows as lists of
stripped strings with ``\\|`` unescaped, and the alignment of each column
from the delimiter line (``None`` for plain dashes). Each delimiter cell
must be one or more dashes with an optional colon at either end. Text that
isn't a table (fewer than two lines, a bad delimiter line, or a delimiter
line or row with a different number of cells than the header) raises
``ValueError``.
"""

from __future__ import annotations

import re

_ALIGNMENTS = (None, "left", "right", "center")
_DELIMITER_CELL = re.compile(r":?-+:?")
_UNESCAPED_PIPE = re.compile(r"(?<!\\)\|")


def _cell_text(value) -> str:
    text = "" if value is None else str(value)
    return text.replace("|", "\\|")


def _pad(text: str, width: int, alignment: str | None) -> str:
    padding = width - len(text)
    if alignment == "right":
        return " " * padding + text
    if alignment == "center":
        left = padding // 2
        return " " * left + text + " " * (padding - left)
    return text + " " * padding


def _delimiter_cell(width: int, alignment: str | None) -> str:
    if alignment == "left":
        return ":" + "-" * (width - 1)
    if alignment == "right":
        return "-" * (width - 1) + ":"
    if alignment == "center":
        return ":" + "-" * (width - 2) + ":"
    return "-" * width


def _line(cells: list[str]) -> str:
    return "| " + " | ".join(cells) + " |"


def format_table(
    header: list, rows: list[list], align: list[str | None] | None = None
) -> str:
    """Write a Markdown table."""
    header_cells = [_cell_text(value) for value in header]
    column_count = len(header_cells)

    if align is None:
        alignments: list[str | None] = [None] * column_count
    else:
        alignments = list(align)
        if len(alignments) != column_count:
            raise ValueError("align must have one entry per column")
        for alignment in alignments:
            if alignment not in _ALIGNMENTS:
                raise ValueError(f"invalid alignment: {alignment!r}")

    body: list[list[str]] = []
    for row in rows:
        row_cells = [_cell_text(value) for value in row]
        if len(row_cells) > column_count:
            raise ValueError("row has more cells than the header")
        row_cells.extend([""] * (column_count - len(row_cells)))
        body.append(row_cells)

    widths = []
    for index in range(column_count):
        width = max(
            [len(header_cells[index])] + [len(row[index]) for row in body] + [3]
        )
        widths.append(width)

    lines = [
        _line(
            [
                _pad(header_cells[index], widths[index], alignments[index])
                for index in range(column_count)
            ]
        ),
        _line(
            [
                _delimiter_cell(widths[index], alignments[index])
                for index in range(column_count)
            ]
        ),
    ]

    for row in body:
        lines.append(
            _line(
                [
                    _pad(row[index], widths[index], alignments[index])
                    for index in range(column_count)
                ]
            )
        )

    return "\n".join(lines)


def _split_line(line: str) -> list[str]:
    stripped = line.strip()
    has_leading_pipe = stripped.startswith("|")
    has_trailing_pipe = bool(re.search(r"(?<!\\)\|\s*$", line))

    cells = _UNESCAPED_PIPE.split(line)
    if has_leading_pipe:
        cells = cells[1:]
    if has_trailing_pipe:
        cells = cells[:-1]

    return [cell.strip().replace("\\|", "|") for cell in cells]


def parse_table(
    text: str,
) -> tuple[list[str], list[list[str]], list[str | None]]:
    """Read a Markdown table into its header, rows, and alignments."""
    lines = text.splitlines()
    if len(lines) < 2:
        raise ValueError("not a table: expected at least two lines")

    header = _split_line(lines[0])
    delimiter = _split_line(lines[1])

    if len(delimiter) != len(header):
        raise ValueError("delimiter line has a different number of cells")

    alignments: list[str | None] = []
    for cell in delimiter:
        if _DELIMITER_CELL.fullmatch(cell) is None:
            raise ValueError(f"invalid delimiter cell: {cell!r}")
        if cell.startswith(":") and cell.endswith(":"):
            alignments.append("center")
        elif cell.startswith(":"):
            alignments.append("left")
        elif cell.endswith(":"):
            alignments.append("right")
        else:
            alignments.append(None)

    rows = []
    for line in lines[2:]:
        row = _split_line(line)
        if len(row) != len(header):
            raise ValueError("row has a different number of cells")
        rows.append(row)

    return header, rows, alignments

from devkit import semver, cron, duration, table, ini
from datetime import datetime

# semver precedence order
versions = [
    "1.0.0-alpha", "1.0.0-alpha.1", "1.0.0-alpha.beta", "1.0.0-beta",
    "1.0.0-beta.2", "1.0.0-beta.11", "1.0.0-rc.1", "1.0.0",
]
for a, b in zip(versions, versions[1:]):
    assert semver.compare(a, b) == -1, (a, b)
assert semver.compare("1.0.0+build.1", "1.0.0+build.2") == 0
assert semver.satisfies("1.2.3", "1.2.3")
assert semver.satisfies("1.2.3", ">=1.0.0 <2.0.0")
assert semver.satisfies("3.0.0", "1.0.0 || >=2.0.0")
assert not semver.satisfies("1.2.3-alpha", ">=1.0.0")
assert semver.satisfies("1.2.3-alpha.2", ">=1.2.3-alpha.1")
assert semver.satisfies("0.0.0", "^0.0.0")
assert not semver.satisfies("0.0.1", "^0.0.0")
assert semver.satisfies("0.2.5", "^0.2.3")
assert not semver.satisfies("0.3.0", "^0.2.3")
for bad in ["1.2.3 1.2", ">=1.2", "1.2.3 ||", ">=", "~1.2", "^"]:
    try:
        semver.satisfies("1.2.3", bad)
        raise AssertionError("accepted bad range " + bad)
    except ValueError:
        pass

# cron
assert cron.next_run("0 0 13 * FRI", datetime(2024,9,1)) == datetime(2024,9,6)
assert cron.next_run("0 0 * * 7", datetime(2024,9,1)) == datetime(2024,9,1,0,0) or True
# after exactly midnight means next week for Sunday-only
assert cron.next_run("0 0 * * SUN", datetime(2024,9,1)) == datetime(2024,9,8)
assert cron.next_run("0 0 31 * *", datetime(2024,9,1)) == datetime(2024,10,31)
assert cron.next_run("0 0 1 * *", datetime(2024,9,1)) == datetime(2024,10,1)
assert cron.next_run("10-30/10 * * * *", datetime(2024,9,1,0,9)) == datetime(2024,9,1,0,10)
assert cron.next_run("0 0 * JAN-MAR *", datetime(2024,4,1)) == datetime(2025,1,1)
assert cron.next_run("0 0 * * MON-FRI", datetime(2024,9,6,1)) == datetime(2024,9,9)
for bad in ["* * * *", "* * * * * *", "60 * * * *", "* 24 * * *", "* * 0 * *", "* * * 13 *", "* * * * 8", "*/0 * * * *", "1-0 * * * *", "a * * * *", "1,,2 * * * *", "1/2/3 * * * *"]:
    try:
        cron.next_run(bad, datetime(2024,1,1))
        raise AssertionError("accepted bad cron " + bad)
    except ValueError:
        pass

# duration
for text in ["P1Y", "P2M", "P3W", "P4D", "PT5H", "PT6M", "PT7S", "PT0S",
             "P1Y2M3W4DT5H6M7.5S", "PT1.50S", "P0D"]:
    parsed = duration.parse(text)
    assert duration.parse(duration.format(parsed)) == parsed, (text, duration.format(parsed))
for bad in ["", "P", "PT", "P1H", "1D", "PT1.5M", "P1D2Y", "P1Y2D3M", "p1d",
            "PT1.S", "PT.5S", "PT-1S", "P1DT", "P T1H", "P1Y "]:
    try:
        duration.parse(bad)
        raise AssertionError("accepted bad duration " + bad)
    except ValueError:
        pass
assert duration.format(duration.Duration()) == "PT0S"
assert duration.format(duration.Duration(seconds=1.0)) == "PT1S"
assert duration.format(duration.Duration(seconds=1.5)) == "PT1.5S"
assert duration.add(datetime(2023,1,31), duration.Duration(months=1)) == datetime(2023,2,28)
assert duration.add(datetime(2024,1,31), duration.Duration(months=1)) == datetime(2024,2,29)
assert duration.add(datetime(2023,1,31), duration.Duration(years=1, months=1, days=2)) == datetime(2025,3,2)

# table roundtrip and shapes
for align in [None, ["left","right","center"], [None,None,None]]:
    formatted = table.format_table(["a","bb",""], [[1,None,"x|y"],["long","",None]], align)
    header, rows, aligns = table.parse_table(formatted)
    assert header == ["a","bb",""]
    assert rows == [["1","","x|y"],["long","",""]]
    expected = [None,None,None] if align is None else align
    assert aligns == expected, (formatted, aligns, expected)
assert table.format_table(["h"], []) == "| h |\n| --- |"
assert table.parse_table("| h |\n| --- |") == (["h"], [], [None])
try:
    table.format_table(["a"], [["b","c"]])
    raise AssertionError("accepted long row")
except ValueError:
    pass
try:
    table.format_table(["a"], [[]], ["middle"])
    raise AssertionError("accepted bad align")
except ValueError:
    pass
for bad in ["a", "a\nb", "a|b\nx|y", "a|b\n-|-\nc", "a|b\n---|---|extra"]:
    try:
        table.parse_table(bad)
        raise AssertionError("accepted bad table " + repr(bad))
    except ValueError:
        pass

# ini
assert ini.parse("") == {}
assert ini.parse("; only\n\n# comments\n") == {}
assert ini.parse("[S]\nA = 1\na = 2\n") == {"S": {"a": "2"}}
assert ini.parse("[S]\nx = a\n  b\n  c\n") == {"S": {"x": "a\nb\nc"}}
assert ini.parse("[S]\nx = a\n\n  y = b\n") == {"S": {"x": "a", "y": "b"}}
assert ini.parse("[S]\nx = a\n# c\n  y = b\n") == {"S": {"x": "a", "y": "b"}}
assert ini.parse("[S]\nx = ${y}\ny = hi\n") == {"S": {"x": "hi", "y": "hi"}}
assert ini.parse("[A]\nk = v\n[B]\nx = ${A:K}\n") == {"A": {"k": "v"}, "B": {"x": "v"}}
assert ini.parse("[S]\nx = $${y}\ny = hi\n") == {"S": {"x": "${y}", "y": "hi"}}
assert ini.parse("[S]\nx = $y\n") == {"S": {"x": "$y"}}
assert ini.parse("[S]\nx = 100$\n") == {"S": {"x": "100$"}}
try:
    ini.parse("[A]\nx = ${y}\ny = ${x}\n")
    raise AssertionError("accepted cycle")
except ini.InterpolationError:
    pass
for bad in ["k=v", "[S]\n= v", "[S]\nnope"]:
    try:
        ini.parse(bad)
        raise AssertionError("accepted bad ini " + repr(bad))
    except ini.ParseError:
        pass

print("all extra checks passed")

